#include "unity.h"
#include "mock_sh1106.h"
#include "mock_platform_io.h"
#include "display.h"
#include "config.h"
#include "logo.h"
#include "display_font.h"

#include <string.h>

#define DISPLAY_WIDTH 128U
#define DISPLAY_HEIGHT 64U
#define LOGO_EXPECTED_X 2U
#define LOGO_EXPECTED_Y 19U
#define LOGO_EXPECTED_WIDTH 124U
#define LOGO_EXPECTED_HEIGHT 26U
#define LOGO_PAGE_COUNT 8U
#define LOGO_PAGE_BYTES 128U

typedef struct
{
    uint8_t pixels[LOGO_PAGE_COUNT][LOGO_PAGE_BYTES];
    unsigned int calls;
    bool page_seen[LOGO_PAGE_COUNT];
    bool invalid_page;
} logo_transfer_t;

static logo_transfer_t logo_transfer;

static bool capture_sh1106_page(sh1106_send_t send, uint8_t address,
                                uint8_t page, const uint8_t *pixels,
                                int cmock_num_calls)
{
    (void)send;
    (void)address;
    (void)cmock_num_calls;
    logo_transfer.calls++;
    if ((page >= LOGO_PAGE_COUNT) || (pixels == NULL))
    {
        logo_transfer.invalid_page = true;
        return true;
    }
    memcpy(logo_transfer.pixels[page], pixels, LOGO_PAGE_BYTES);
    logo_transfer.page_seen[page] = true;
    return true;
}

static void render_splash(void)
{
    sensors_snapshot_t readings;

    memset(&readings, 0, sizeof(readings));
    memset(&logo_transfer, 0, sizeof(logo_transfer));
    /* UINT32_MAX is beyond stabilization from the timestamp initialized to 0,
     * including the unsigned elapsed-time calculation used by display_process. */
    display_process(UINT32_MAX, &readings);
}

void setUp(void)
{
    memset(&logo_transfer, 0, sizeof(logo_transfer));

    platform_io_init_IgnoreAndReturn(true);
    platform_io_now_ms_IgnoreAndReturn(0U);
    platform_io_log_Ignore();
    sh1106_init_IgnoreAndReturn(true);
    sh1106_page_StubWithCallback(capture_sh1106_page);
    sh1106_enable_IgnoreAndReturn(true);

    TEST_ASSERT_TRUE(display_init(0U));
    /* Exclude any page writes that initialization may have used to clear RAM. */
    memset(&logo_transfer, 0, sizeof(logo_transfer));
}

void tearDown(void)
{
}

void test_FR_001_01(void)
{
    unsigned int min_x = DISPLAY_WIDTH;
    unsigned int min_y = DISPLAY_HEIGHT;
    unsigned int max_x = 0U;
    unsigned int max_y = 0U;
    bool found_white_pixel = false;

    render_splash();

    TEST_ASSERT_FALSE(logo_transfer.invalid_page);
    TEST_ASSERT_EQUAL_INT((int)LOGO_PAGE_COUNT, (int)logo_transfer.calls);
    for (unsigned int page = 0U; page < LOGO_PAGE_COUNT; page++)
    {
        TEST_ASSERT_TRUE(logo_transfer.page_seen[page]);
        for (unsigned int x = 0U; x < DISPLAY_WIDTH; x++)
        {
            for (unsigned int bit = 0U; bit < 8U; bit++)
            {
                if ((logo_transfer.pixels[page][x] & (uint8_t)(1U << bit)) != 0U)
                {
                    const unsigned int y = (page * 8U) + bit;
                    found_white_pixel = true;
                    if (x < min_x) min_x = x;
                    if (x > max_x) max_x = x;
                    if (y < min_y) min_y = y;
                    if (y > max_y) max_y = y;
                }
            }
        }
    }

    TEST_ASSERT_TRUE(found_white_pixel);
    TEST_ASSERT_EQUAL_INT((int)LOGO_EXPECTED_X, (int)min_x);
    TEST_ASSERT_EQUAL_INT((int)LOGO_EXPECTED_Y, (int)min_y);
    TEST_ASSERT_EQUAL_INT((int)(LOGO_EXPECTED_X + LOGO_EXPECTED_WIDTH - 1U), (int)max_x);
    TEST_ASSERT_EQUAL_INT((int)(LOGO_EXPECTED_Y + LOGO_EXPECTED_HEIGHT - 1U), (int)max_y);
    TEST_ASSERT_EQUAL_INT((int)LOGO_EXPECTED_WIDTH, (int)(max_x - min_x + 1U));
    TEST_ASSERT_EQUAL_INT((int)LOGO_EXPECTED_HEIGHT, (int)(max_y - min_y + 1U));
}

void test_FR_001_02(void)
{
    render_splash();

    TEST_ASSERT_FALSE(logo_transfer.invalid_page);
    TEST_ASSERT_EQUAL_INT((int)LOGO_PAGE_COUNT, (int)logo_transfer.calls);
    for (unsigned int page = 0U; page < LOGO_PAGE_COUNT; page++)
    {
        TEST_ASSERT_TRUE(logo_transfer.page_seen[page]);
        /* Exact page-byte equality verifies the renderer sends the bitmap
         * unchanged: black zero bits, white set bits, and no scaling/inversion. */
        TEST_ASSERT_EQUAL_MEMORY(&display_logo[page * LOGO_PAGE_BYTES],
                                 logo_transfer.pixels[page], LOGO_PAGE_BYTES);
    }

    /* The expected bitmap keeps the outer display border black. */
    for (unsigned int page = 0U; page < LOGO_PAGE_COUNT; page++)
    {
        TEST_ASSERT_EQUAL_INT(0, logo_transfer.pixels[page][0]);
        TEST_ASSERT_EQUAL_INT(0, logo_transfer.pixels[page][1]);
        TEST_ASSERT_EQUAL_INT(0, logo_transfer.pixels[page][126]);
        TEST_ASSERT_EQUAL_INT(0, logo_transfer.pixels[page][127]);
    }
    for (unsigned int x = 0U; x < DISPLAY_WIDTH; x++)
    {
        TEST_ASSERT_EQUAL_INT(0, logo_transfer.pixels[0][x]);
        TEST_ASSERT_EQUAL_INT(0, logo_transfer.pixels[1][x]);
        TEST_ASSERT_EQUAL_INT(0, logo_transfer.pixels[6][x]);
        TEST_ASSERT_EQUAL_INT(0, logo_transfer.pixels[7][x]);
    }
}
